"""Deterministic authoring source for the two additional private scenario JSON files."""
import json
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'apps/api'))
from app.engine.mechanics.analytics_v1 import SOURCE_HASH,build_rows
root=Path(__file__).resolve().parents[1]/'apps/api/content/scenarios'

def action(id,label,cost,description,parameters=None,requires=None,mutation=True):
    return dict(id=id,label=label,cost=cost,description=description,parameters=parameters or [],requires=requires or [],mutation=mutation)
def param(name,label,type,choices=None):return dict(name=name,label=label,type=type,choices=choices or [])
def cmd(type,**payload):return dict(type=type,payload=payload)
def artifact(id,title,type,teammate,body,requires=None):return dict(id=id,title=title,type=type,teammate=teammate,body=body,requires=requires or [])
def teammate(id,name,role,welcome,fallback):return dict(id=id,name=name,role=role,persona='Be concise, grounded, and explicit about missing evidence. Never execute actions.',welcome=welcome,fallback=fallback)
def fact(id,text,people,artifact_id=None):return dict(id=id,text=text,teammates=people,artifact_id=artifact_id)
base=dict(schema_version='1',content_version=1,engine_version='1',scoring_version='1')
inv={**base,'scenario_id':'inventory-race','slug':'inventory-race','mechanics_id':'inventory_v1',
'metadata':dict(title='One item. Two promises.',description='A flash sale is selling stock twice. Stop the oversells, repair the race, and reconcile the promises already made.',company='Common Goods',role='Backend engineer',difficulty='Intermediate',duration='25–35 minutes',tags=['Concurrency','Data integrity','Tradeoffs'],briefing='Welcome to Common Goods, a fictional shop running a flash sale. Distinct customers received reservations for the same stock. Ten invalid reservations already exist. Maya owns the reservation service; Leo knows the stock ledger. You can serialize requests, suspend sales, deploy a reviewed patch and reconcile invalid reservations. Each simulated minute brings a fresh lot of 20 units and 25 requests. Isolated tests do not add fixture reservations to the incident ledger. The logical cap is 20; reading speed and chat are free. Score: diagnosis 20, outcome 40, verification 20, structured communication 10, judgment 10.',objectives=['Deploy atomic reservations without queue serialization','Stop new oversells','Reconcile every invalid reservation','Keep sales running with 20 of 25 requests accepted']),
'initial_state':dict(sales='running',queue=False,patch='legacy',invalid_reservations=10,invalid_ids=[f'INIT-{i:02d}' for i in range(1,11)],legitimate_ids=[f'INIT-L{i:03d}' for i in range(1,41)],cancelled_invalid_ids=[],new_oversells=0,lost_sales=0),
'teammates':[teammate('maya','Maya','Platform engineer','The reservation alert is active. We should inspect the request trace before choosing a patch.','I know the alert is active. Open the trace to inspect the concurrency behavior together.'),teammate('leo','Leo','Product / data engineer','Our invariant is simple: accepted reservations cannot exceed physical stock. Let’s inspect the ledger.','Open the ledger so I can discuss the stock and reservations that actually exist.')],
'artifacts':[
artifact('inventory.trace','Concurrent reservation trace','log','maya','HISTORICAL INCIDENT EVIDENCE · t=0\nSKU contested-01 stock=1\nrequest R16 idempotency-key=k16 READ stock=1\nrequest R21 idempotency-key=k21 READ stock=1\nrequest R16 WRITE stock=0; INSERT reservation R16\nrequest R21 WRITE stock=0; INSERT reservation R21\nBoth requests are distinct, not retries. The same interleaving occurs for five contested SKUs. A legacy tick accepts 25 requests against 20 units.'),
artifact('inventory.ledger','Stock and reservation ledger','table','leo','HISTORICAL INCIDENT EVIDENCE · t=0\nlot,physical_units,accepted_reservations,invalid\nprior-A,20,25,5\nprior-B,20,25,5\nInitial invalid IDs: INIT-01 through INIT-10. Forty legitimate prior reservations must remain.\nEach new lot: fifteen ordinary SKUs and five contested SKUs, one unit each. R01–R15 buy ordinary SKUs. R16–R20 compete with R21–R25 for contested stock. The later five reservations are invalid under the legacy schedule. Current invalid IDs are recorded as T{tick}-R21 through R25. Reconciliation must cancel only invalid reservations.'),
artifact('inventory.patch_review','Reservation patch review','diagram','maya','REVIEWED IMPLEMENTATION OPTIONS · isolated design evidence\nLegacy: read stock → check positive → write stale decrement → insert reservation.\nIdempotency-only: deduplicate a repeated request key, then execute the same legacy sequence. R16 and R21 have different keys, so the race remains.\nAtomic: in one database transaction, conditionally decrement stock WHERE available > 0 and insert a reservation only when that decrement succeeds.\nA serialization queue prevents overlapping writes but adds p95=900ms in this simulation. The atomic path needs no queue and has p95=100ms. Repairing future reservations does not cancel old invalid reservations. The race test bypasses the queue.', ['inventory.trace','inventory.ledger'])],
'facts':[fact('inventory.alert','The reservation alert is active.',['maya']),fact('inventory.invariant','Accepted reservations must not exceed physical stock.',['leo']),fact('inventory.interleaving','Distinct requests with different keys both read stock=1 before writing stock=0.',['maya'],'inventory.trace'),fact('inventory.backlog','Two historical lots each accepted 25 reservations for 20 units. Ten initial invalid reservations require reconciliation; forty legitimate reservations must remain.',['leo'],'inventory.ledger'),fact('inventory.options','Idempotency-only retains the race for distinct keys. The reviewed atomic transaction conditionally decrements stock and inserts the reservation together. A queue contains concurrency with extra latency.',['maya'],'inventory.patch_review')],
'action_catalog':[action('inventory.set_queue','Set reservation queue',1,'Serialize simulated reservations to contain concurrent writes, at a latency cost.',[param('enabled','Enable serialization queue','boolean')]),action('inventory.set_sales','Set sale availability',1,'Suspend or resume simulated sales. Suspension prevents oversells but loses sales.',[param('status','Sale status','enum',['running','suspended'])]),action('inventory.deploy_patch','Deploy reservation patch',2,'Deploy a reviewed implementation to the simulated reservation service.',[param('kind','Patch implementation','enum',['atomic','idempotency_only','legacy'])],['inventory.patch_review']),action('inventory.reconcile','Reconcile invalid reservations',2,'Cancel only currently invalid reservations. Requires no new oversells.',requires=['inventory.ledger']),action('inventory.test_race','Test concurrent reservations',1,'Run the isolated 25-request race fixture, bypassing the queue.',mutation=False),action('inventory.test_ledger','Verify ledger and throughput',1,'Check invalid reservations, retained legitimate reservations, and current live throughput.',mutation=False)],
'diagnosis_choices':[dict(id='duplicate_retry_keys',label='Repeated retry keys created duplicate reservations'),dict(id='non_atomic_stock_reservation',label='A non-atomic stock check allowed concurrent reservations'),dict(id='warehouse_feed_lag',label='The warehouse stock feed is delayed')],
'rubric':dict(cause_id='non_atomic_stock_reservation',diagnosis_artifacts=['inventory.trace','inventory.ledger'],explanation='The legacy read/check/write schedule lets distinct requests reserve the same final unit. Idempotency protects retries, not concurrent distinct purchases. Queue serialization can contain the race. The atomic patch repairs the invariant; reconciliation removes the existing invalid backlog. Full success also requires running sales without the queue and current race/ledger checks.'),
'hints':[dict(id='inventory.hint1',text='Compare the request trace with the physical-stock ledger.'),dict(id='inventory.hint2',text='Look at whether the two requests have the same key, and compare the reviewed atomic boundary with the legacy sequence.',requires=['inventory.trace','inventory.ledger'])],
'golden_commands':[cmd('inventory.set_queue',enabled=True),cmd('evidence.open',artifact_id='inventory.trace'),cmd('evidence.open',artifact_id='inventory.ledger'),cmd('evidence.open',artifact_id='inventory.patch_review'),cmd('inventory.deploy_patch',kind='atomic'),cmd('inventory.reconcile'),cmd('inventory.set_queue',enabled=False),cmd('inventory.test_race'),cmd('inventory.test_ledger')],
'golden_expected':dict(simulation_time=11,new_oversells=0,lost_sales=0,invalid_reservations=0),
'negative_paths':[[cmd('inventory.set_sales',status='suspended'),cmd('inventory.test_ledger')],[cmd('inventory.test_race')]]}
ana={**base,'scenario_id':'analytics-timezone','slug':'analytics-timezone','mechanics_id':'analytics_v1',
'metadata':dict(title='The drop that wasn’t.',description='Paid conversion appears to have fallen overnight. Separate a behavior change from a reporting error, then publish a verified explanation.',company='Daylight Studio',role='Data engineer',difficulty='Intermediate',duration='20–30 minutes',tags=['Analytics','Time zones','Validation'],briefing='Welcome to Daylight Studio, a fictional commerce team. Daily paid conversion appears to fall from 60% to 40%. The store uses America/Los_Angeles. Maya can discuss source ingestion and Leo knows the business-date requirement. Inspect timestamped sources and transformations, repair the materialized report and publish a verified simulated stakeholder update. The dataset is frozen: logical ticks never create payments. A winter boundary fixture tests the transformation but never contributes to incident totals. Cap: 20 simulated minutes. Score: diagnosis 20, outcome 40, verification 20, structured communication 10, judgment 10.',objectives=['Use the named store time zone','Correct both affected daily report rows','Preserve 90 orders and $9,000 across affected dates','Publish a current correct verified report']),
'initial_state':dict(normalization='utc',report_mode='utc',source_hash=SOURCE_HASH,rows=build_rows('utc'),publications=[],incorrect_publications=0),
'teammates':[teammate('maya','Maya','Platform engineer','The ingestion run completed. Let’s inspect the source timestamps before blaming customer behavior.','I can confirm ingestion status, but we need to open the sources to discuss the actual records.'),teammate('leo','Leo','Product / data engineer','The business expects store-local reporting dates. Let’s inspect how each dataset is grouped.','The business-date requirement is store local. Open the transforms before we infer their implementation.')],
'artifacts':[
artifact('analytics.sources','Session and payment sources','table','maya','HISTORICAL INCIDENT EVIDENCE · frozen affected dates\nStore zone: America/Los_Angeles. Every order is $100. Ingestion completed with no missing or duplicate payment IDs.\npaid_at_utc,orders,revenue\n2025-07-15T17:00:00Z,40,$4000\n2025-07-16T02:00:00Z,20,$2000\n2025-07-16T17:00:00Z,30,$3000\nLocal-date sessions: July 15 = 100; July 16 = 50.\nBaseline July 14 conversion = 60% is context only and excluded from affected-date totals. Affected-date totals: 90 paid orders, $9000.'),
artifact('analytics.transforms','Business-date transformations','diagram','leo','HISTORICAL INCIDENT EVIDENCE · t=0\nSessions → America/Los_Angeles business date → group by date.\nPayments → extract UTC calendar date → group by date.\nJoin both aggregates on date.\nCurrent materialized report: July 15 = 40/100, 40%, $4000; July 16 = 50/50, 100%, $5000.\nChanging a transformation does not rebuild the materialized table. A rebuild records the source and transformation fingerprints. A fixed UTC-7 offset matches summer only; the named zone follows seasonal transitions.'),
artifact('analytics.boundary_spec','Summer and winter boundary tests','text','leo','ISOLATED TEST-FIXTURE OUTPUT SPECIFICATION\nSummer: July 16, 2025 02:00Z → July 15 in America/Los_Angeles (UTC-7).\nWinter: January 16, 2025 07:30Z → January 15 in America/Los_Angeles (UTC-8).\nThe winter example is a separate fixture, never an incident payment.\nVerify both boundary dates and both materialized daily rows. Expected report: July 15 = 60/100, 60%, $6000; July 16 = 30/50, 60%, $3000. Totals remain 90 orders / $9000. Passing aggregate totals alone cannot establish correct daily attribution.',['analytics.transforms'])],
'facts':[fact('analytics.ingestion','The ingestion run completed.',['maya']),fact('analytics.requirement','Stakeholders expect store-local business dates in America/Los_Angeles.',['leo']),fact('analytics.source_groups','Sources contain 40 payments at July 15 17:00Z, 20 at July 16 02:00Z, and 30 at July 16 17:00Z, with no duplicates or missing records.',['maya'],'analytics.sources'),fact('analytics.grouping','Sessions group by store-local date; payments currently extract UTC date. Configuration changes require a materialized rebuild.',['leo'],'analytics.transforms'),fact('analytics.boundaries','Summer and winter boundaries use different offsets. The named zone maps both fixtures to the previous local date; the winter fixture is excluded from incident revenue.',['leo'],'analytics.boundary_spec')],
'action_catalog':[action('analytics.set_normalization','Set payment date normalization',1,'Configure how payment timestamps become business dates. The materialized report is not rebuilt.',[param('mode','Normalization mode','enum',['utc','fixed_minus_7','named_zone'])],['analytics.transforms']),action('analytics.rebuild','Rebuild materialized report',3,'Recompute both affected dates and record current source and transform fingerprints.'),action('analytics.restart_ingestion','Restart ingestion',1,'Repeat the successful ingestion process without changing grouping or source data.'),action('analytics.test_totals','Verify affected-date totals',1,'Check report freshness, 90 unique orders, and $9,000 across affected dates.',requires=['analytics.sources'],mutation=False),action('analytics.test_boundaries','Test summer and winter boundaries',1,'Check isolated seasonal boundary fixtures and both current daily rows.',requires=['analytics.boundary_spec'],mutation=False),action('analytics.publish','Publish stakeholder report',1,'Store an immutable simulated report snapshot. Incorrect or unverified publications are recorded.')],
'diagnosis_choices':[dict(id='missing_payment_ingestion',label='Payment ingestion dropped a group of orders'),dict(id='date_bucket_timezone_mismatch',label='The joined datasets use inconsistent time-zone date buckets'),dict(id='real_conversion_decline',label='Customer conversion truly declined on July 15')],
'rubric':dict(cause_id='date_bucket_timezone_mismatch',diagnosis_artifacts=['analytics.sources','analytics.transforms'],explanation='Sessions use store-local business dates while payments used UTC dates. Twenty late-local-evening July 15 payments landed in July 16 UTC. Normalize payment timestamps to America/Los_Angeles before extracting the date, rebuild the report, and verify both totals and summer/winter boundaries before publication. A fixed UTC-7 offset fits July but fails winter; total revenue alone cannot prove attribution.'),
'hints':[dict(id='analytics.hint1',text='Compare the source timestamp groups with the report’s two daily rows.'),dict(id='analytics.hint2',text='Compare how each transform extracts a date, then check whether one fixed offset works for both boundary fixtures.',requires=['analytics.transforms'])],
'golden_commands':[cmd('evidence.open',artifact_id='analytics.sources'),cmd('evidence.open',artifact_id='analytics.transforms'),cmd('evidence.open',artifact_id='analytics.boundary_spec'),cmd('analytics.set_normalization',mode='named_zone'),cmd('analytics.rebuild'),cmd('analytics.test_totals'),cmd('analytics.test_boundaries'),cmd('analytics.publish')],
'golden_expected':dict(simulation_time=10,incorrect_publications=0),
'negative_paths':[[cmd('analytics.restart_ingestion')],[cmd('evidence.open',artifact_id='analytics.sources'),cmd('analytics.test_totals'),cmd('analytics.publish')]]}
for definition in (inv,ana):
    folder=root/definition['slug'];folder.mkdir(exist_ok=True);(folder/'scenario.json').write_text(json.dumps(definition,indent=2)+'\n')
